import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.ChTAMbUy.js";const g=JSON.parse('{"title":"LLM Usage and Cost","description":"","frontmatter":{},"headers":[],"relativePath":"1.10/admin/llm_usage.md","filePath":"versions/1.10/admin/llm_usage.md","lastUpdated":1795427690000}'),i={name:"1.10/admin/llm_usage.md"};function r(l,e,n,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="llm-usage-and-cost" tabindex="-1">LLM Usage and Cost <a class="header-anchor" href="#llm-usage-and-cost" aria-label="Permalink to &quot;LLM Usage and Cost&quot;">​</a></h1><p>The <strong>LLM Usage and Cost</strong> admin page shows LLM calls through Agent Gateway across all workspaces, for external and self-hosted models alike, and is where administrators set model prices. Open it under <strong>Admin</strong> in the sidebar. Only platform administrators can open it.</p><p>Use this page to answer platform-wide questions, such as which workspaces spend the most or which models are used without a price. For one workspace, including MCP, agent, and other non-LLM calls, use <a href="./../platform/gateway_usage.html">Gateway Usage</a>. For external providers only, use the usage card on <a href="./external_models.html#external-model-usage">External Models</a>.</p><h2 id="usage-and-cost" tabindex="-1">Usage and Cost <a class="header-anchor" href="#usage-and-cost" aria-label="Permalink to &quot;Usage and Cost&quot;">​</a></h2><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/llm-usage/llm-usage-and-cost-card-framed.png" alt="Usage and Cost with LLM call, token, and cost totals, the trend, and breakdowns by source and workspace" loading="lazy"></p><p>Select a time window: <strong>Last hour</strong>, <strong>Last 24 hours</strong> (default), <strong>Last 7 days</strong>, or <strong>Max (N days)</strong>. N defaults to 10 and is limited by how long the gateway keeps its access logs.</p><p>LLM calls are calls to language, embedding, and rerank models. <strong>By source</strong> uses the same sources as <a href="./../platform/gateway_usage.html#sources">Gateway Usage</a>. <strong>By workspace</strong> lists calls that cannot be attributed to a workspace as <strong>No workspace</strong>.</p><p><strong>Some calls have no price set</strong> means the cost total is partial; see <a href="#model-pricing">Model Pricing</a>. Calls that bypass Agent Gateway are not included. Costs are estimates for observability, not billing records.</p><h2 id="model-pricing" tabindex="-1">Model Pricing <a class="header-anchor" href="#model-pricing" aria-label="Permalink to &quot;Model Pricing&quot;">​</a></h2><p>Agent Gateway calculates the cost of each LLM call from its model price catalog. It ships with built-in prices for common hosted models. Use <strong>Model pricing</strong> to price models it does not know, such as self-hosted models, or to set negotiated prices.</p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/llm-usage/llm-usage-model-pricing-panel-framed.png" alt="Model pricing panel with a custom price and a model used without a price" loading="lazy"></p><p><strong>Used in the last 24 hours without a price</strong> lists models that received calls but have neither a built-in nor a custom price. Their calls show tokens but no cost.</p><h3 id="add-or-edit-a-price" tabindex="-1">Add or Edit a Price <a class="header-anchor" href="#add-or-edit-a-price" aria-label="Permalink to &quot;Add or Edit a Price&quot;">​</a></h3><ol><li><p>Select <strong>Add price</strong>, or <strong>Edit price</strong> in a row&#39;s menu. A model under <strong>Used in the last 24 hours without a price</strong> has its own <strong>Add price</strong> button that pre-fills the provider and model.</p></li><li><p>Enter <strong>Provider</strong> and <strong>Model</strong> as the gateway logs them:</p><ul><li><strong>Provider</strong> is the logged provider name. Self-hosted and custom OpenAI-compatible providers usually log <code>custom</code>.</li><li><strong>Model</strong> is the model ID returned in the response, or the requested model if the response names none.</li></ul><p>Both are catalog keys. They are not necessarily the provider connection name or the route ID of a workspace grant.</p></li><li><p>Enter rates in USD per million tokens: <strong>Input</strong>, <strong>Output</strong>, <strong>Cache read</strong>, <strong>Cache write</strong>, and <strong>Reasoning</strong>. Fill in at least one. An empty field keeps the gateway&#39;s built-in price for that rate.</p></li><li><p>Select <strong>Save price</strong>.</p></li></ol><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/llm-usage/llm-usage-add-price-dialog-framed.png" alt="Add model price dialog pre-filled for a self-hosted model" loading="lazy"></p><p>New calls use the price within a few minutes, without a gateway restart. <strong>Delete price</strong> removes your custom rates; the gateway then falls back to its built-in price for that model, if it has one.</p><p>If another administrator changed pricing at the same time, saving fails with a conflict message and keeps your draft. Cancel, select <strong>Reload pricing</strong>, review the current values, and save again.</p><h3 id="start-from-default-prices" tabindex="-1">Start from Default Prices <a class="header-anchor" href="#start-from-default-prices" aria-label="Permalink to &quot;Start from Default Prices&quot;">​</a></h3><p>Select <strong>Show default prices</strong> to browse the built-in prices of the deployed Agent Gateway release, for example to check whether a model already has a price.</p><ul><li>Only flat token rates are listed. A dash means the catalog has no flat rate for that model, not that usage is free.</li><li>The list is a snapshot published with the platform release, not read from the running gateway. Current provider prices may differ.</li><li>Models you have priced are marked <strong>Overridden</strong>. Select <strong>Edit price</strong> to change your price, or <strong>Override price</strong> on another model to open the editor pre-filled with its default rates.</li></ul><p>Saving an override changes only your custom prices; the default prices stay unchanged. If the platform does not publish a snapshot, the view shows <strong>Default prices are not published by the platform.</strong></p><p><img src="https://storage.googleapis.com/prokube-docs-pictures/pk-docs/screenshots/admin/llm-usage/llm-usage-default-prices-dialog-framed.png" alt="Default model prices with release version and snapshot date, filtered by a search" loading="lazy"></p><h3 id="pricing-and-historical-usage" tabindex="-1">Pricing and Historical Usage <a class="header-anchor" href="#pricing-and-historical-usage" aria-label="Permalink to &quot;Pricing and Historical Usage&quot;">​</a></h3><p>The gateway records a call&#39;s cost when it serves the call. A new or changed price is not applied retroactively:</p><ul><li>Calls served before the change keep the cost recorded at the time. Calls that had no price stay unpriced and show <strong>No price set</strong>.</li><li>In a window that mixes old and new traffic, call and token totals include all calls, but the cost covers only calls that were priced when served. For example, with 100 calls before pricing and 10 after, the totals cover 110 calls and the cost covers 10.</li></ul><h3 id="manage-prices-with-gitops" tabindex="-1">Manage Prices with GitOps <a class="header-anchor" href="#manage-prices-with-gitops" aria-label="Permalink to &quot;Manage Prices with GitOps&quot;">​</a></h3><p>The panel stores prices in the ConfigMap <code>agentgateway-model-catalog</code> in the <code>agentgateway-system</code> namespace, key <code>catalog.json</code>. The platform does not ship this ConfigMap; the first save in the panel creates it. Prices are merged over the built-in catalog:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;providers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;models&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;my-model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rates&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;input&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.50&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;output&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.50&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}}}}}</span></span></code></pre></div><ul><li>Rates are decimal strings in USD per million tokens. <code>cacheRead</code>, <code>cacheWrite</code>, and <code>reasoning</code> are optional.</li><li>The catalog can hold up to 500 provider and model pairs and 256 KiB.</li><li>If the file is not valid JSON, the gateway keeps the last valid prices. Calls are not affected.</li></ul><p>Use either GitOps or the panel to manage this ConfigMap, not both. The panel keeps content it does not manage and rejects stale changes, but a GitOps tool restores its own version on the next sync.</p><p>To verify a price, send a new call to the model, then check its cost in the key&#39;s <a href="./../platform/api_keys.html#request-activity">Request Activity</a> or on <a href="./../platform/gateway_usage.html">Gateway Usage</a>, or search the gateway logs for <code>agw.ai.usage.cost.total</code>. See <a href="./operations_runbooks.html#auditing-llm-usage">Auditing LLM Usage</a>.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./external_models.html">External Models</a></li><li><a href="./../platform/gateway_usage.html">Gateway Usage</a></li><li><a href="./../platform/system_status.html#agent-gateway-traffic">System Status</a></li><li><a href="./operations_runbooks.html#auditing-llm-usage">Auditing LLM Usage</a></li></ul>',33)])])}const u=a(i,[["render",r]]);export{g as __pageData,u as default};
